<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'; import { computed } from 'vue'; import PresentationForm from '@/components/catalog/PresentationForm.vue'; import InputError from '@/components/InputError.vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input';
type Item = { id: string; code: string; name: string }; type Unit = { id: string; code: string; name: string }; type Option = { id: string; sku: string; name: string }; type Component = { presentation_id: string; quantity: string; name: string }; type Presentation = { id: string; sku: string; name: string; stock_unit_id: string; conversion_to_item_base: string; is_purchasable: boolean; is_sellable: boolean; is_stockable: boolean; is_active: boolean; barcode: string; minimum_sale_price: number | null; components: Component[] };
const props = defineProps<{ item: Item; presentation: Presentation; units: Unit[]; componentOptions: Option[] }>(); const componentForm = useForm({ components: props.presentation.components.map((component) => ({ presentation_id: component.presentation_id, quantity: component.quantity })) }); const availableToAdd = computed(() => props.componentOptions.filter((option) => !componentForm.components.some((component) => component.presentation_id === option.id))); const addComponent = () => { const option = availableToAdd.value[0]; if (option) componentForm.components.push({ presentation_id: option.id, quantity: '1' }); }; const removeComponent = (index: number) => componentForm.components.splice(index, 1); const saveComponents = () => componentForm.put(`/catalog/items/${props.item.id}/presentations/${props.presentation.id}/components`, { preserveScroll: true });
</script>
<template><Head :title="presentation.name" /><main class="flex flex-1 flex-col gap-6 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">{{ presentation.name }}</h1><p class="text-sm text-muted-foreground">{{ item.name }} · {{ presentation.sku }}</p></header><section class="max-w-3xl rounded-xl border bg-card p-5"><PresentationForm :submit-url="`/catalog/items/${item.id}/presentations/${presentation.id}`" method="put" :units="units" :cancel-url="`/catalog/items/${item.id}/edit`" :initial="presentation" /></section><section class="max-w-3xl rounded-xl border bg-card p-5"><div class="mb-4 flex items-center justify-between gap-3"><div><h2 class="font-semibold">Composición del paquete</h2><p class="text-sm text-muted-foreground">Déjalo vacío si esta presentación no es un paquete.</p></div><Button type="button" size="sm" variant="outline" :disabled="availableToAdd.length === 0" @click="addComponent">Agregar componente</Button></div><form class="space-y-3" @submit.prevent="saveComponents"><div v-for="(component, index) in componentForm.components" :key="index" class="grid grid-cols-[1fr_9rem_auto] items-center gap-2"><select v-model="component.presentation_id" required class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="option in componentOptions" :key="option.id" :value="option.id">{{ option.name }} ({{ option.sku }})</option></select><Input v-model="component.quantity" type="number" min="0.000001" step="any" required /><Button type="button" size="sm" variant="ghost" @click="removeComponent(index)">Quitar</Button></div><InputError :message="componentForm.errors.components" /><div class="flex justify-end border-t pt-4"><Button type="submit" :disabled="componentForm.processing">Guardar componentes</Button></div></form></section></main></template>
